                                  '    for path, expected in CLUB_PRODUCT_SHA256.items():\n'
                                  "        require(digest(contents[path]) == expected, 'Changed actual club "
                                  "product: ' + path)\n"
                                  '    for path, row in CLUB_SOURCE_ROWS.items():\n'
                                  "        require(digest(contents[path]) == row['after_sha256'], 'Changed "
                                  "actual club support/source: ' + path)\n"
                                  '    runner = contents[RUNNER_PATH]\n'
                                  '    pins = re.findall(rb"(?m)^CONTRACT_SHA256 = \'([0-9a-f]{64})\'$", '
                                  'runner)\n'
                                  "    require(len(pins) == 1 and pins[0].decode() == digest(raw), 'Unknown "
                                  "complete actual club contract pin')\n"
                                  '    club_current_readiness_source(runner)\n'
                                  '    module = contents[SELF_PATH]\n'
                                  "    require(digest(module) == IMPLEMENTATION_SHA256, 'Loaded club "
                                  "admission differs from actual bytes')\n"
                                  '    slot = b"ADMISSION_FINGERPRINT = \'" + ADMISSION_FINGERPRINT.encode() '
                                  '+ b"\'"\n'
                                  '    require(module.count(slot) == 1 and digest(module.replace(slot, '
                                  'b"ADMISSION_FINGERPRINT = \'<SELF>\'", 1)) == ADMISSION_FINGERPRINT,\n'
                                  "            'Changed complete club admission fingerprint')\n"
                                  '    validate_external_source_template(root, module)\n'
                                  '    club_predecessor_source(PROFILE_PATH, contents[PROFILE_PATH])\n'
                                  '    for path in CLUB_SUPPORT_BEFORE:\n'
                                  "        require(value['feature_batch_support_sha256'].get(path) == "
                                  'digest(contents[path]),\n'
                                  "                'Missing or changed actual club support registration: ' + "
                                  'path)\n'
                                  '    _club_restore_contract(value)\n'
                                  '    return value, contents\n'
                                  '\n'
                                  '\n'
                                  'def club_predecessor_contract(value):\n'
                                  '    """Return exact e2b contract; current input requires physical current '
                                  'admission."""\n'
                                  '    if digest(encode(value)) == CLUB_PRE_CONTRACT_SHA256:\n'
                                  '        return copy.deepcopy(value)\n'
                                  '    raw = (ROOT / CONTRACT_PATH).read_bytes()\n'
                                  "    require(encode(value) == raw, 'Changed or foreign club predecessor "
                                  "contract argument')\n"
                                  '    club_authenticate_current(raw, ROOT)\n'
                                  '    return _club_restore_contract(value)\n'
                                  '\n'
                                  '\n'
                                  'def club_predecessor_fixture_source(path, raw, current_contract):\n'
                                  '    """Construct genuine e2b/54 fixture bytes, never backfill a partial '
                                  'current root."""\n'
                                  '    if path == CONTRACT_PATH:\n'
