                                  '\n'
                                  'def _club_transaction_hashes(root, paths):\n'
                                  '    values = {}\n'
                                  '    for relative in paths:\n'
                                  '        path = root / relative\n'
                                  '        if path.is_symlink() or path.resolve() != path:\n'
                                  "            raise ValueError('Aliased current transaction input: ' + "
                                  'relative)\n'
                                  '        values[relative] = digest(path.read_bytes())\n'
                                  '    return values\n'
                                  '\n'
                                  'def _club_check_transaction(state):\n'
